sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },

	isDatePast: function(strDate) {
		gs.info("isDatePast called with: " + strDate);

		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);

		var today = rightnow.getDate();
		var neededDate = testdate.getDate();

		// If the testdate is before rightnow, return true, else return false

		// Old check:
		// if (neededDate.before(today)) {
		// 	return true;
		// } else {
		// 	return false;
		// }

		// New check: Cleaner than old one. Directly returns the boolean output.
		return neededDate.before(today);
	},

	isDateToday: function(strDate) {
		gs.info("isDateToday called with: " + strDate);

		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);

		var today = rightnow.getDate();
		var neededDate = testdate.getDate();

		// If the testdate is today, return true, else return false

		// Old check:
		// if (neededDate.compareTo(today) === 0) {
		// 	return true;
		// } else {
		// 	return false;
		// }

		// New check: Cleaner than old one. Directly returns the boolean output.
		return neededDate.compareTo(today) === 0;
	},

    type: 'NeedItUtils'
};
